head.script:
scwin.showFloatingLayer = function(title, width, height, url, modal, usePost, postData) {
    var top = document.documentElement.scrollTop + document.documentElement.clientHeight / 2 - parseInt(height) / 2;
    var left = document.documentElement.scrollLeft + document.documentElement.clientWidth / 2 - parseInt(width) / 2;
    var tmp = url.split("/");
    tmp = tmp.reverse();
    var filename = tmp[0];
    var popupId = "Pop_" + filename.split(".")[0];
    var popupIframeId = "PopIf_" + filename.split(".")[0]
    scwin.makeCommonPopup(popupId, popupIframeId, title, width, height, top, left, modal == false ? false : true);
    /*
    eval("popup1_"+popupIdNum).show();
    eval("popup1_iframe"+popupIdNum).setSrc(url);
    */
    eval(popupId).show();
    eval(popupIframeId).setSrc(url);
}
scwin.makeCommonPopup = function(popupId, popupIframeId, title, width, height, top, left, modal, idx) {
    var scrolling = "auto";
    WebSquare.util.dynamicCreate(popupId, "floatingLayer", {
        fullContentArea: true,
        style: "position: relative ;left:" + left + "px;top:" + top + "px;width:" + width + "px;height:" + height + "px;display:none;z-index:4001",
        useModal: modal,
        className: "pop_lay",
        title: title,
        xmlEvents: [{
            name: "onclose",
            action: "script",
            param: {
                handler: function(e) {
                    console.log("onclose");
                    WebSquare.wUnit.getObjById(popupIframeId).setSrc("");
                    WebSquare.wUnit.getObjById(popupIframeId).remove();
                    WebSquare.wUnit.getObjById(popupId).remove();
                    WebSquare.wUnit.getJq(".pop_lay").last().css("z-index", "4001");
                    if (WebSquare.wUnit.getJq(".pop_lay").length == 0) { //마지막 팝업이 닫힐 경우에는 modal을 닫는다
                        WebSquare.wUnit.getJq("#_modal").css("display", "none");
                    }
                }
            }
        }]
    }, WebSquare.getBody());
    WebSquare.wUnit.getJq(".pop_lay").css("z-index", "3999");
    WebSquare.wUnit.getJq("#" + popupId).css("z-index", "4001");
    WebSquare.util.dynamicCreate(popupIframeId, "iframe", {
        style: "position: relative ;left: 0px;width: 100%;height: 100%;",
        name: popupIframeId,
        scrolling: scrolling
    }, eval(popupId + "_contents"));
}
scwin.hideFloatingLayer = function(popupId) {
    var tmp = popupId.split("_");
    var popupIframeId = "PopIf_" + tmp[1];
    WebSquare.wUnit.getObjById(popupIframeId).setSrc("");
    WebSquare.wUnit.getObjById(popupIframeId).remove();
    WebSquare.wUnit.getObjById(popupId).remove();
    WebSquare.wUnit.getJq(".pop_lay").last().css("z-index", "4001");
    if (WebSquare.wUnit.getJq(".pop_lay").length == 0) { //마지막 팝업이 닫힐 경우에는 modal을 닫는다
        WebSquare.wUnit.getJq("#_modal").css("display", "none");
    }
}
scwin.setGridData = function(data, popupIdx) {
    dataList1.setJSON(data);
    //hideFloatingLayer(popupIdx);
}
scwin.trigger1_onclick = function(e) {};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    // Test step 1. 샘플파일을 실행 후 '팝업1오픈'을 클릭한다.
    //1. Run the sample file and click 'Open pop-up 1'.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "2000");
    // verify step 1. 작은 팝업창이보여지고 (우측스크롤바의 우측끝의 여백이 보이지 않고) 아래끝의 스크롤바의 아래끝영역사이의 여백이 보이지 않는다.(이전에는 여백이 보여짐)
    //1. A small pop-up window is displayed (no margins at the right end of the right scroll bar), no margins between the bottom end areas of the scroll bar at the bottom end (previously the margins are shown)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#Pop_floatingLayerWPF1019WSQ2207popup').length == 1", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#Pop_floatingLayerWPF1019WSQ2207popup_contents').width() >= 500", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
